output = "import 'package:flutter/material.dart';\n\n"
output += "List<Path> getSvgPaths() {\n"
output += "  return [\n"

def parse_svg_path(svg_path):
    tokens = re.findall(r'([MCLZz])|(-?\d*\.?\d+)', svg_path)
    dart_code = "    Path()\n"
    
    cmd = ''
    points = []
    
    def process_command(cmd, points):
        code = ""
        if cmd == 'M':
            if len(points) >= 2:
                code += f"      ..moveTo({points[0]}, {points[1]})\n"
        elif cmd == 'C':
            for i in range(0, len(points), 6):
                if i+5 < len(points):
                    code += f"      ..cubicTo({points[i]}, {points[i+1]}, {points[i+2]}, {points[i+3]}, {points[i+4]}, {points[i+5]})\n"
        elif cmd in ('Z', 'z'):
            code += "      ..close()\n"
        elif cmd == 'L':
            if len(points) >= 2:
                for i in range(0, len(points), 2):
                     code += f"      ..lineTo({points[i]}, {points[i+1]})\n"
        return code

    for token in tokens:
        if token[0]: # command
            if cmd:
                dart_code += process_command(cmd, points)
            cmd = token[0]
            points = []
            if cmd in ('Z', 'z'):
                dart_code += process_command(cmd, [])
                cmd = ''
        elif token[1]: # number
            points.append(float(token[1]))
            
    if cmd and points:
         dart_code += process_command(cmd, points)
         
    return dart_code + "  "

for p in svg_paths:
    output += parse_svg_path(p) + ",\n"

output += "  ];\n}"

with open('svg_paths.dart', 'w') as f:
    f.write(output)
